const $=id=>document.getElementById(id),app=$('app'),canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false}),overlay=$('overlay');
const storeKey='vespergrave.v3',saveKey=storeKey+'.run',profileKey=storeKey+'.profile',settingsKey=storeKey+'.settings';
function stored(key){try{return localStorage.getItem(key);}catch{return null;}}
function write(key,value){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,typeof value==='string'?value:JSON.stringify(value));return true;}catch{return false;}}
let profile=readProfile(stored(profileKey)),settings={music:.3,sfx:.65,voice:.8,haptics:true,shake:true,flashes:true,fps:60,large:false,reduced:false};try{Object.assign(settings,JSON.parse(stored(settingsKey)||'{}'));}catch{}
for(const key of ['music','sfx','voice'])settings[key]=clamp(Number(settings[key])||0,0,1);settings.fps=Number(settings.fps)===30?30:60;
const images=new Map(),thumbs=new Map();
async function loadImage(name){if(images.has(name))return images.get(name).promise;const asset=ASSETS[name];if(!asset)throw Error('Missing illustration: '+name);const img=new Image(),entry={img,ready:false,promise:null};entry.promise=new Promise((resolve,reject)=>{img.onload=()=>{entry.ready=true;resolve(img);};img.onerror=()=>reject(Error('Unable to read '+name));});images.set(name,entry);img.src=asset.image;return entry.promise;}
function imageReady(name){const e=images.get(name);if(!e){loadImage(name).catch(showError);return null;}return e.ready?e.img:null;}
function pruneEnemyImages(biomes){const keep=new Set(biomes);for(const e of ENEMIES)if(!keep.has(e.biome))images.delete(e.asset);}
const illustratedFrames=new Map(),illustratedTags=new Map();
function frames(name){if(!illustratedFrames.has(name))illustratedFrames.set(name,Object.values(ASSETS[name]?.frames??{}));return illustratedFrames.get(name);}
function tag(name,label){if(!illustratedTags.has(name))illustratedTags.set(name,new Map((ASSETS[name]?.meta?.frameTags??[]).map(t=>[t.name,t])));return illustratedTags.get(name).get(label);}
function frameAt(name,label,seconds=0,loop=true){const t=tag(name,label)??tag(name,'s-idle');if(!t)return 0;const f=frames(name),total=f.slice(t.from,t.to+1).reduce((n,a)=>n+a.duration,0);let time=seconds*1000;if(loop)time%=Math.max(1,total);for(let n=t.from;n<=t.to;n++){time-=f[n].duration;if(time<0)return n;}return t.to;}
function drawFrame(c,name,index,x,y,w=null,h=null){const img=imageReady(name),f=frames(name)[index]?.frame;if(!img||!f)return;const a=ASSETS[name].meta.anchor??{x:0,y:0};c.drawImage(img,f.x,f.y,f.w,f.h,Math.round(x-a.x),Math.round(y-a.y),w??f.w,h??f.h);}
async function thumbnail(name,label='s-idle',size=112){const key=name+label+size;if(thumbs.has(key))return thumbs.get(key);const img=await loadImage(name),f=frames(name)[frameAt(name,label)]?.frame,c=document.createElement('canvas');c.width=size;c.height=size;const x=c.getContext('2d');x.imageSmoothingEnabled=false;if(f){const anchor=ASSETS[name].meta.anchor??{x:f.w/2,y:f.h},scale=name.startsWith("hero-")?size/88:1;x.drawImage(img,f.x,f.y,f.w,f.h,Math.round(size/2-anchor.x*scale),Math.round(size*.92-anchor.y*scale),Math.round(f.w*scale),Math.round(f.h*scale));}else x.drawImage(img,0,0,size,size);const url=c.toDataURL();thumbs.set(key,url);return url;}
async function iconThumb(name,label){const key=name+label;if(thumbs.has(key))return thumbs.get(key);const img=await loadImage(name),index=tag(name,label)?.from??0,f=frames(name)[index].frame,c=document.createElement('canvas');c.width=f.w;c.height=f.h;const x=c.getContext('2d');x.imageSmoothingEnabled=false;x.drawImage(img,f.x,f.y,f.w,f.h,0,0,f.w,f.h);const url=c.toDataURL();thumbs.set(key,url);return url;}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function button(text,command,{primary=false,small=false,disabled=false,extra=''}={}){return `<button class="button ${primary?'primary':''} ${small?'small':''}" data-command="${command}" ${disabled?'disabled':''} ${extra}>${text}</button>`;}
function header(title,subtitle='',back='close'){return `<header class="panel-header"><div><span class="eyebrow">Vespergrave</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close-button" data-command="${back}" aria-label="Back">×</button></header>`;}
function showError(error){$('loading').hidden=false;$('load-message').textContent='Unable to load: '+error.message;console.error(error);}
function persistProfile(){write(profileKey,profile);}
const audio={context:null,master:null,musicGain:null,musicNodes:[],voice:null,voiceTimer:null,musicTimer:null,started:false,
 start(){if(this.started){this.context?.resume().catch(()=>{});return;}try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;this.context=new A();this.master=this.context.createGain();this.master.connect(this.context.destination);this.musicGain=this.context.createGain();this.musicGain.gain.value=settings.music*.15;this.musicGain.connect(this.master);this.started=true;this.context.resume().catch(()=>{});this.compose();this.musicTimer=setInterval(()=>this.compose(),22000);}catch{}},
 compose(){if(!this.context||document.hidden)return;const c=this.context,t=c.currentTime;for(const freq of [55,82.4069,110,130.8128]){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+3);g.gain.setValueAtTime(.045,t+18);g.gain.linearRampToValueAtTime(0,t+24);o.connect(g);g.connect(this.musicGain);o.start(t);o.stop(t+24);}const notes=[220,0,261.6256,246.9417,164.8138,0,220,130.8128];notes.forEach((freq,n)=>{if(!freq)return;this.tone(freq,.8,'sine',.12,n*2.7,this.musicGain);this.tone(freq*2,.5,'sine',.035,n*2.7,this.musicGain);});},
 tone(freq,duration,type='sine',volume=.15,delay=0,destination=null){if(!this.context)return;const c=this.context,o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);if(type==='triangle')o.frequency.exponentialRampToValueAtTime(Math.max(25,freq*.55),t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*(destination?1:settings.sfx)),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(destination??this.master);o.start(t);o.stop(t+duration+.03);},
 sfx(type){if(!this.started||settings.sfx<=0)return;if(['hit','kill','heavy'].includes(type)){this.tone(type==='kill'?83:130,.12,'triangle',.23);this.tone(720,.045,'square',.025);}else if(type==='swing')this.tone(260,.08,'triangle',.07);else if(type==='hurt'||type==='death')this.tone(65,.35,'triangle',.23);else if(['heal','level','chest','boss-death'].includes(type)){[220,330,440].forEach((f,n)=>this.tone(f,.7,'sine',.13,n*.12));}else if(type==='block')this.tone(880,.2,'sine',.15);else if(['cast','skill'].includes(type)){this.tone(520,.32,'sine',.12);this.tone(780,.24,'sine',.07,.05);}else if(type==='roll')this.tone(105,.08,'triangle',.08);},
 stopVoice(){clearTimeout(this.voiceTimer);this.voiceTimer=null;if(this.voice){this.voice.pause();this.voice.onended=null;this.voice=null;}},
 speak(id,onEnd=null){this.stopVoice();app.dataset.narration=id;app.dataset.narrationState="loading";const src=VO_ASSETS[id],script=VO_SCRIPT.find(s=>s.id===id),fallback=()=>{this.voiceTimer=setTimeout(()=>{this.voiceTimer=null;onEnd?.();},clamp((script?.text.split(' ').length??12)/2.2,4,18)*1000);};if(!src||settings.voice<=0){fallback();return;}const voice=new Audio(src);this.voice=voice;voice.volume=settings.voice;voice.onplaying=()=>{app.dataset.narrationState="playing";};voice.onended=()=>{app.dataset.narrationState="ended";this.voice=null;onEnd?.();};voice.onerror=fallback;voice.play().catch(fallback);},
 apply(){if(this.musicGain&&this.context)this.musicGain.gain.setTargetAtTime(settings.music*.15,this.context.currentTime,.15);if(this.voice)this.voice.volume=settings.voice;}
};
let game=null,panel='title',selectedHero='knight',selectedDifficulty='oathbound',bagTab='equipment',selectedItem=null,codexBiome=0,codexEnemy=null,onboardingPage=0,cinemaIndex=0,cinemaPages=null,cinemaDone=null,viewEpoch=0,lastAutoSave=0,lastUI=0,lastTime=0,lastRender=0,lastPanelState='',backgroundKey='',background=null,lastBiome=null,gameOverShown=false;
const keys=new Set(),queued=new Set(),touch=new TouchInput();
const clearTouch=bindTouchControls(touch,document,()=>togglePause(),()=>!!game&&!panel&&game.state==='playing');
function clearInput(){keys.clear();queued.clear();clearTouch?.();}
function setPanel(name,html=''){clearInput();panel=name;viewEpoch++;overlay.innerHTML=html;app.dataset.screen=name??'playing';updateVisibility();if(name&&game)saveRun();}
function panelHtml(content){return `<section class="panel screen-fade">${content}</section>`;}
async function eventDialog(){const info=game?.eventInfo();if(!info||info.status!=='pending')return;const epoch=viewEpoch+1;setPanel('event',panelHtml(header(info.name,game.biome.name+' · A chance encounter')+`<div class="event-illustration"><img id="event-art" alt="${escapeHtml(info.name)}"></div><p class="event-story">${escapeHtml(info.description)}</p><p class="event-resources">${Math.ceil(game.player.hp)} HEALTH · ${game.gold} GOLD · ${game.flasks} FLASKS</p><div class="event-choices">${info.choices.map(c=>`<button class="event-choice" data-event-choice="${c.id}" ${c.available?'':'disabled'}><strong>${escapeHtml(c.label)}</strong><span>${escapeHtml(c.detail)}</span>${!c.available?'<small>Not enough resources</small>':''}</button>`).join('')}</div><p class="fine-print">Your choice lasts for this descent. The chamber remembers it when you return.</p>`));const src=await iconThumb('event-art',info.id);if(viewEpoch===epoch&&$('event-art'))$('event-art').src=src;}
function saveRun(){if(game){const s=game.serialize();write(saveKey,s);}}
function updateVisibility(){const play=!!game&&!panel,active=play&&game.state==='playing';$('hud').hidden=!play;$('top-actions').hidden=!active;$('touch-controls').hidden=!active;$('tutorial').hidden=!active||!game.tutorial;if(!active){$('context').hidden=true;$('toast').hidden=true;$('boss-hud').hidden=true;$('event-hud').hidden=true;}app.classList.toggle('large-controls',!!settings.large);app.classList.toggle('reduced-motion',!!settings.reduced);}
function title(){audio.stopVoice();game=null;backgroundKey='';const canContinue=!!Campaign.restore(stored(saveKey),arenaHeight());setPanel('title',`<section class="screen menu-screen screen-fade"><img class="screen-art" src="${ASSETS['cinematic-0'].image}" alt="A ruined cathedral under a waning moon"><div class="wallet">${profile.embers} EMBERS</div><div class="wordmark"><span class="eyebrow">A descent beyond the last light</span><h1>VESPERGRAVE</h1><p>THE BELL BELOW</p><div class="ornament">◇</div></div><div class="menu-actions">${canContinue?button('Continue descent','continue',{primary:true}):''}${button('New game','new-game',{primary:!canContinue})}${button('The chronicles','title-codex')}</div><nav class="menu-links" aria-label="Main menu"><button data-command="settings">Settings</button><button data-command="about">About</button><button data-command="share">Share</button><button data-command="rate">Rate</button></nav><p class="menu-meta">100 FLOORS · 10 REALMS · THREE UNFINISHED OATHS<br>BEST DESCENT ${String(profile.bestFloor).padStart(2,'0')} / 100 · ${GAME_VERSION}</p></section>`);}
async function heroSelect(){const epoch=viewEpoch+1;setPanel('hero-select',panelHtml(header('Choose your oath','Three souls. Three ways into the dark.','title')+`<div class="hero-list">${HEROES.map(h=>`<button class="hero-card ${h.id===selectedHero?'selected':''}" data-hero="${h.id}"><img data-hero-art="${h.id}" alt="${h.name}, ${h.title}"><div><h2>${h.name}</h2><h3>${h.title}</h3><p>${h.role}<br>${h.passive}</p></div></button>`).join('')}</div><p class="hero-story" id="hero-story"></p><div class="difficulty-row">${DIFFICULTIES.map(d=>`<button class="${d.id===selectedDifficulty?'selected':''}" data-difficulty="${d.id}">${d.name}</button>`).join('')}</div><p class="difficulty-copy" id="difficulty-copy"></p><div id="hero-upgrade"></div><div class="sticky-actions">${button('Carry the last ember','begin',{primary:true,extra:'id="begin" class="full-width button primary"'})}</div>`));updateHeroSelection();for(const h of HEROES){const src=await thumbnail(h.asset);if(viewEpoch!==epoch)return;const img=overlay.querySelector(`[data-hero-art="${h.id}"]`);if(img)img.src=src;}}
function updateHeroSelection(){const h=HEROES.find(h=>h.id===selectedHero),d=DIFFICULTIES.find(d=>d.id===selectedDifficulty);for(const b of overlay.querySelectorAll('[data-hero]'))b.classList.toggle('selected',b.dataset.hero===selectedHero);for(const b of overlay.querySelectorAll('[data-difficulty]'))b.classList.toggle('selected',b.dataset.difficulty===selectedDifficulty);$('hero-story').textContent=h.story;$('difficulty-copy').textContent=d.description;const rank=profile.ranks[h.id],cost=(rank+1)*20;$('hero-upgrade').innerHTML=`<div class="row"><label>Ember bond · ${rank} / 10<small>Each bond grants +2.5% starting health and damage.</small></label>${button(rank===10?'Bond complete':`Strengthen · ${cost} embers`,'bond',{small:true,disabled:rank===10||profile.embers<cost})}</div>`;}
function onboarding(){const cards=[{heading:'A kingdom that forgot the dawn',text:'Explore one complete chamber at a time. The small map shows connected rooms; a guardian seals the stair below.',asset:'room-abbey'},{heading:'Move with your own rhythm',text:'Touch the open floor and drag. Your D-pad appears beneath your thumb and follows it. Use the separate buttons to attack, guard, roll and cast.',asset:'hero-knight'},{heading:'Carry what the dark gives back',text:'Collect equipment, grow your skills and rest at hearths. Your descent saves automatically. Death ends the run; earned embers strengthen your next oath.',asset:'hero-seer'}],card=cards[onboardingPage];setPanel('onboarding',`<section class="panel onboarding screen-fade"><span class="eyebrow">Before the first bell</span><img class="onboarding-art" id="onboarding-art" alt="${card.heading}"><div class="dots">${cards.map((_,n)=>`<i class="${n===onboardingPage?'active':''}"></i>`).join('')}</div><h1>${card.heading}</h1><p>${card.text}</p>${button(onboardingPage===2?'I am ready':'Continue','onboarding-next',{primary:true})}<button class="text-button" data-command="onboarding-skip">Skip introduction</button></section>`);if(onboardingPage===0)$('onboarding-art').src=ASSETS[card.asset].image;else thumbnail(card.asset,'s-idle',200).then(src=>{if($('onboarding-art'))$('onboarding-art').src=src;});}
function beginFlow(){audio.start();if(stored(saveKey)&&!game){setPanel('overwrite',panelHtml(header('A descent remains','Starting again will replace your active descent.','hero-select')+`<p class="body-copy">Your permanent embers and bonds remain with you. The current dungeon and its equipment will be lost.</p><div class="button-row">${button('Keep the descent','continue')}${button('Begin anew','confirm-new',{primary:true})}</div>`));return;}confirmNew();}
function confirmNew(){write(saveKey,null);if(!profile.onboarded){onboardingPage=0;onboarding();}else if(!profile.introSeen)playCinematic(INTRO,startRun);else startRun();}
function afterOnboarding(){profile.onboarded=true;persistProfile();if(profile.introSeen)startRun();else playCinematic(INTRO,startRun);}
function playCinematic(pages,done){cinemaPages=pages;cinemaIndex=0;cinemaDone=done;cinematicPage();}
function cinematicPage(){const p=cinemaPages[cinemaIndex],epoch=viewEpoch+1;setPanel('cinematic',`<section class="screen cinematic screen-fade"><img class="screen-art" src="${ASSETS['cinematic-'+p.scene].image}" alt="${p.heading.toLowerCase()}"><button class="cinematic-skip" data-command="cinematic-skip">SKIP</button><div class="cinematic-caption"><span class="eyebrow">${cinemaPages===INTRO?'The chronicle of Vespergrave':'The final oath'}</span><h1>${p.heading}</h1><p>${p.text}</p><span class="cinematic-hint">${settings.voice>0?'NARRATION · ENGLISH':'CAPTIONS · ENGLISH'}</span><br><button class="text-button" data-command="cinematic-next">Continue</button></div><div class="cinematic-progress">${cinemaPages.map((_,n)=>`<i class="${n<=cinemaIndex?'done':''}"></i>`).join('')}</div></section>`);audio.speak(p.id,()=>{if(viewEpoch===epoch&&panel==='cinematic')cinematicNext();});}
function cinematicNext(){audio.stopVoice();if(cinemaIndex+1<cinemaPages.length){cinemaIndex++;cinematicPage();}else finishCinematic();}
function finishCinematic(){audio.stopVoice();const done=cinemaDone;cinemaDone=null;profile.introSeen=true;persistProfile();done?.();}
function arenaHeight(){return Math.max(438,canvas.height-32);}
async function loadChapter(index){pruneEnemyImages([index]);await Promise.all([loadImage('room-'+BIOMES[index].id),...ENEMIES.filter(e=>e.biome===index).map(e=>loadImage(e.asset))]);}
async function startRun(){audio.start();const hero=HEROES.find(h=>h.id===selectedHero);await Promise.all([loadImage(hero.asset),loadChapter(0)]);game=new Campaign({hero:selectedHero,difficulty:selectedDifficulty,height:arenaHeight(),rank:profile.ranks[selectedHero],tutorial:!profile.tutorialDone});profile.runs++;persistProfile();gameOverShown=false;lastBiome=0;setPanel(null);backgroundKey='';audio.speak('hero-'+selectedHero,()=>{if(game&&!panel)audio.speak('biome-'+game.biome.id);});saveRun();syncSkillIcons();}
async function continueRun(){const restored=Campaign.restore(stored(saveKey),arenaHeight());if(!restored){write(saveKey,null);title();return;}audio.start();await Promise.all([loadImage(restored.hero.asset),loadChapter(restored.biome.index)]);game=restored;selectedHero=game.hero.id;selectedDifficulty=game.difficulty.id;lastBiome=game.biome.index;gameOverShown=false;setPanel(null);backgroundKey='';syncSkillIcons();game.notify('The ember kept your place.');}
function togglePause(){if(!game||!['playing','dying'].includes(game.state))return;if(panel){if(['pause','settings','about','rate'].includes(panel)){setPanel(null);return;}closePanel();return;}setPanel('pause',panelHtml(header('A moment of silence','Your descent is saved.','resume')+`<div class="body-copy">${game.hero.name}, ${game.hero.title}<br><strong>${game.biome.name} · Floor ${game.floor} / 100</strong></div><div class="menu-actions full-width">${button('Return to the descent','resume',{primary:true})}${button('Equipment and skills','bag')}${button('Settings','settings')}${button('Save and return to title','save-title')}</div><p class="keyboard-hint">WASD / ARROWS · MOVE<br>J · ATTACK　K · GUARD　SPACE · ROLL<br>Q / E · SKILLS　R · HEAL　F · USE　I · SATCHEL</p>`));}
let returnPanel='title';
function closePanel(){audio.stopVoice();if(game){if(panel==='bag'){selectedItem=null;setPanel(null);}else if(['settings','about','rate','codex'].includes(panel)){if(returnPanel==='pause'){setPanel(null);togglePause();}else if(returnPanel==='bag')openBag(bagTab);else title();}else setPanel(null);}else title();}
function showSettings(){if(!['settings'].includes(panel))returnPanel=game?(panel==='bag'?'bag':'pause'):'title';setPanel('settings',panelHtml(header('Settings','Shape the sound and feel of your descent.')+`<p class="section-label">SOUND</p>${[['music','Music','Original bells and ambient score'],['sfx','Effects','Steel, footsteps and spellcraft'],['voice','Narration','Offline English voice-over']].map(([id,title,detail])=>`<div class="row"><label for="setting-${id}">${title}<small>${detail}</small></label><input id="setting-${id}" data-setting="${id}" type="range" min="0" max="100" value="${settings[id]*100}" aria-label="${title} volume"></div>`).join('')}<p class="section-label">PLAY</p>${[['haptics','Haptic feedback'],['shake','Impact shake'],['flashes','Spell flashes'],['large','Larger touch buttons'],['reduced','Reduced menu motion']].map(([id,title])=>`<div class="row"><label for="setting-${id}">${title}</label><input id="setting-${id}" data-setting="${id}" type="checkbox" ${settings[id]?'checked':''}></div>`).join('')}<div class="row"><label for="setting-fps">Frame rate<small>30 FPS uses less battery.</small></label><select id="setting-fps" data-setting="fps"><option value="60" ${settings.fps===60?'selected':''}>60 FPS</option><option value="30" ${settings.fps===30?'selected':''}>30 FPS</option></select></div><div class="divider"></div>${button('Replay opening chronicle','replay-intro',{small:true})}<p class="fine-print">All game content and narration work offline. Progress and preferences stay on this device.</p>`));}
function showAbout(){returnPanel=game?'pause':'title';setPanel('about',panelHtml(header('About the bell',GAME_TITLE+' · '+GAME_SUBTITLE)+`<img src="${ASSETS['vespergrave-icon'].image}" width="96" height="96" class="pixel" alt="Vespergrave knight emblem"><p class="body-copy">An original dark fantasy roguelike about the promises we carry after the world has forgotten them.</p><p class="body-copy"><strong>100 procedural floors</strong> across ten authored realms. Sixty enemy designs, ten bosses, three heroes, nine skills and one hundred equipment and consumable designs.</p><p class="body-copy">Pixel art and animation are authored through MCP Aseprite. English narration is performed with Deepgram voices. Music and sound are composed for this game.</p><p class="muted">Version ${GAME_VERSION}<br>Created for Fareza · 2026<br>Source and Android builds are available on GitHub.</p><div class="button-row">${button('Project page','project',{small:true})}${button('Share the game','share',{small:true})}</div><p class="fine-print">Vespergrave, its characters and its lore are original. No third-party game characters, artwork or music are included.</p>`));}
async function shareGame(){const text=`Vespergrave: The Bell Below — an offline dark fantasy roguelike. Descend 100 floors through ten forgotten realms. ${PROJECT_URL}`;try{if(window.VespergraveNative?.share){window.VespergraveNative.share(text);return;}if(navigator.share){await navigator.share({title:'Vespergrave: The Bell Below',text,url:PROJECT_URL});return;}await navigator.clipboard.writeText(text);uiNotice('Game link copied. Share it wherever you like.');}catch(e){if(e.name!=='AbortError')uiNotice('Share link: '+PROJECT_URL);}}
function uiNotice(text){const e=$('toast');e.textContent=text;e.hidden=false;setTimeout(()=>{if(panel)e.hidden=true;},4500);}
function showRating(){returnPanel=game?'pause':'title';setPanel('rate',panelHtml(header('How was your descent?','Your rating is saved on this device.')+`<p class="body-copy">Tell the ember how this adventure felt. Every rating helps you keep a record of your experience.</p><div class="rating-stars" role="group" aria-label="Rate the game from one to five stars">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" class="${profile.rating>=n?'selected':''}" aria-label="${n} ${n===1?'star':'stars'}">★</button>`).join('')}</div><p id="rating-copy" class="muted" style="text-align:center">${profile.rating?'Your rating: '+profile.rating+' / 5. Thank you for playing.':'Choose a star above.'}</p><div class="button-row">${button('Share your adventure','share',{small:true})}${button('Send feedback','feedback',{small:true})}</div><p class="fine-print">There is no store listing yet. Your selection remains a private, local rating; feedback opens the project’s issue page.</p>`));}
async function openBag(tabName=bagTab){if(!game)return;bagTab=tabName;selectedItem=null;renderBag();}
function tabBar(){return `<nav class="tabs" aria-label="Satchel pages">${[['equipment','Equipment'],['skills','Skills'],['codex','Bestiary'],['journal','Journal']].map(([id,text])=>`<button data-bag-tab="${id}" class="${bagTab===id?'selected':''}">${text}</button>`).join('')}</nav>`;}
function statName(k){return({maxHp:'Health',maxFocus:'Focus',damage:'Damage',defense:'Defence',speed:'Speed',crit:'Critical chance',lifesteal:'Life steal',staminaRegen:'Stamina recovery'})[k]??k;}
function statValue(k,v){return Math.round(v)+(['crit','lifesteal'].includes(k)?'%':'');}
async function renderBag(){if(!game)return;const p=game.player,epoch=viewEpoch+1;let content=header('The wanderer’s satchel',`${game.gold} gold · ${game.essence} essence · Level ${game.level}`,'close')+tabBar();
 if(bagTab==='equipment'){
  content+=`<div class="stats-grid">${['maxHp','damage','defense','speed','maxFocus','crit'].map(k=>`<div class="stat"><b>${statValue(k,p[k])}</b>${statName(k)}</div>`).join('')}</div><div class="equip-grid">${EQUIP_SLOTS.map(slot=>{const item=game.inventory.find(i=>i.uid===game.equipment[slot]),b=item&&ITEM_BY_ID[item.baseId];return `<button class="equip-slot" ${item?`data-item="${item.uid}"`:''}><span>${slot.toUpperCase()}</span>${item?`<img data-item-icon="${item.baseId}" alt=""><small style="color:${RARITIES[item.quality].color}">${b.name}</small>`:'<small style="margin-top:25px">Empty slot</small>'}</button>`;}).join('')}</div><p class="section-label">INVENTORY · ${game.inventory.length} / 60</p><div id="item-detail"></div><div class="inventory-list">${game.inventory.map(item=>{const b=ITEM_BY_ID[item.baseId],worn=Object.values(game.equipment).includes(item.uid);return `<button class="item-row" data-item="${item.uid}"><img data-item-icon="${item.baseId}" alt=""><div><h3 style="color:${RARITIES[item.quality].color}">${escapeHtml(item.name)}${worn?' · WORN':''}</h3><small>Level ${item.level} · ${RARITIES[item.quality].name} · ${b.kind}${b.hero?' · '+HEROES.find(h=>h.id===b.hero).name:''}</small></div></button>`;}).join('')}</div>`;
 }
 if(bagTab==='skills'){content+=`<p class="body-copy">${game.hero.passive} Equip two skills. Strengthen them with essence earned during this descent.</p>`+SKILLS.filter(s=>s.hero===game.hero.id).map(s=>{const rank=game.skillRanks[s.id]??0,locked=game.level<s.level;return `<article class="skill-card ${locked?'locked':''}"><div><img data-skill-icon="${s.id}" alt=""><div><h2>${s.name}</h2><small>${locked?'Unlocks at level '+s.level:`${s.cost} focus · ${s.cooldown}s cooldown · Rank ${rank} / 3`}</small></div></div><p>${s.description}</p><div class="button-row">${button(game.skills[0]===s.id?'Slot I equipped':'Equip slot I','skill-equip',{small:true,disabled:locked,extra:`data-id="${s.id}" data-slot="0"`})}${button(game.skills[1]===s.id?'Slot II equipped':'Equip slot II','skill-equip',{small:true,disabled:locked,extra:`data-id="${s.id}" data-slot="1"`})}</div>${button(rank===3?'Fully strengthened':`Strengthen · ${(rank+1)*6} essence`,'skill-upgrade',{small:true,disabled:locked||rank===3||game.essence<(rank+1)*6,extra:`data-id="${s.id}"`})}</article>`;}).join('');}
 if(bagTab==='codex')content+=codexBody();
 if(bagTab==='journal')content+=journalBody();
 setPanel('bag',panelHtml(content));await fillPanelArt(epoch);}
async function fillPanelArt(epoch=viewEpoch){pruneEnemyImages([...(game?[game.biome.index]:[]),codexBiome]);const tasks=[];for(const img of overlay.querySelectorAll('[data-item-icon]'))tasks.push(iconThumb('campaign-items',img.dataset.itemIcon).then(src=>{if(viewEpoch===epoch)img.src=src;}));for(const img of overlay.querySelectorAll('[data-skill-icon]'))tasks.push(iconThumb('campaign-skills',img.dataset.skillIcon).then(src=>{if(viewEpoch===epoch)img.src=src;}));for(const img of overlay.querySelectorAll('[data-enemy-art]')){const e=ENEMY_BY_ID[img.dataset.enemyArt];tasks.push(thumbnail(e.asset,'s-idle',144).then(src=>{if(viewEpoch===epoch)img.src=src;}));}await Promise.all(tasks);}
function selectItem(uid){const item=game?.inventory.find(i=>i.uid===uid);if(!item)return;selectedItem=uid;const base=ITEM_BY_ID[item.baseId],worn=Object.values(game.equipment).includes(uid),valid=!base.hero||base.hero===game.hero.id,consumable=!base.slot,previous=game.inventory.find(i=>i.uid===game.equipment[base.slot]);const root=$('item-detail');if(!root)return;root.innerHTML=`<article class="item-detail"><span class="eyebrow">${RARITIES[item.quality].name} · Level ${item.level} ${base.kind}</span><h2 style="color:${RARITIES[item.quality].color}">${escapeHtml(item.name)}</h2><p>${base.lore}</p><dl>${Object.entries(item.stats).map(([k,v])=>{const delta=v-(previous?.stats[k]??0);return `<dt>${statName(k)}</dt><dd>+${statValue(k,v)} ${previous&&!worn?`<span style="color:${delta>=0?'#91baa1':'#cc8a79'}">(${delta>=0?'+':''}${delta})</span>`:''}</dd>`;}).join('')}</dl><div class="button-row">${button(consumable?'Use item':worn?'Unequip':'Equip','item-equip',{small:true,primary:true,disabled:!valid,extra:`data-uid="${uid}"`})}${button(`Salvage · ${Math.round(item.value/2)} gold`,'item-salvage',{small:true,disabled:worn,extra:`data-uid="${uid}"`})}</div>${!valid?`<p>Only ${HEROES.find(h=>h.id===base.hero).name} can wield this weapon.</p>`:''}</article>`;root.scrollIntoView({block:'nearest',behavior:settings.reduced?'instant':'smooth'});}
function journalBody(){return `<p class="section-label">THE DESCENT</p><p class="body-copy"><strong>${game.hero.name}, ${game.hero.title}</strong><br>${game.hero.story}</p><div class="result-stats"><span>Realm<b>${game.biome.name}</b></span><span>Floor<b>${game.floor} / 100</b></span><span>Oaths broken<b>${Math.floor((game.floor-1)/10)}</b></span><span>Enemies defeated<b>${game.kills}</b></span><span>Time beneath<b>${formatTime(game.runTime)}</b></span><span>Dungeon seed<b>${game.seed}</b></span></div><p class="body-copy">${game.biome.line} A guardian waits in the northern chamber. Side passages may hold equipment, a keeper’s shop, or a hearth.</p><p class="section-label">THE TEN REALMS</p>${BIOMES.map(b=>`<p class="muted"><span style="color:${b.index<=game.biome.index?'#d3bb8c':'#677980'}">${String(b.from).padStart(2,'0')}–${b.to} · ${b.name}</span><br>${b.index<=game.biome.index?b.line:'An unwritten page of the descent.'}</p>`).join('')}<p class="section-label">CONTROLS</p><p class="muted">Touch and drag the floor to move. Hold ATTACK to chain three strikes, GUARD to brace, and tap ROLL to pass through a blow. Skills spend focus. Hearths refill your healing flask.</p><p class="keyboard-hint">WASD / ARROWS · MOVE<br>J · ATTACK　K · GUARD　SPACE · ROLL<br>Q / E · SKILLS　R · HEAL　F · USE　I · SATCHEL</p>`;}
function codexBody(){const b=BIOMES[codexBiome],seen=new Set([...profile.discovered,...(game?.seen??[])]);return `<div class="row"><button class="close-button" data-command="codex-prev" aria-label="Previous biome">‹</button><div style="text-align:center"><span class="eyebrow">REALM ${codexBiome+1} / 10</span><h2 style="font-size:20px;font-weight:400;margin:7px 0">${b.name}</h2></div><button class="close-button" data-command="codex-next" aria-label="Next biome">›</button></div><p class="muted" style="text-align:center">${b.line}</p><div class="codex-grid">${ENEMIES.filter(e=>e.biome===codexBiome).map(e=>`<button class="codex-card" data-enemy="${e.id}"><img data-enemy-art="${e.id}" alt="${e.name}"><span>${e.name}</span><small>${e.boss?'REALM BOSS':e.behavior.toUpperCase()} · ${seen.has(e.id)?'ENCOUNTERED':'UNDISCOVERED'}</small></button>`).join('')}</div><p class="fine-print">All sixty illustrations can be inspected here. Entries marked encountered have appeared in your descents.</p>`;}
async function showCodex(){returnPanel=game?'bag':'title';setPanel('codex',panelHtml(header('The forgotten souls','Sixty designs. Ten unfinished realms.')+codexBody()));await fillPanelArt();}
async function enemyDetail(id){const e=ENEMY_BY_ID[id];if(!e)return;codexEnemy=id;const epoch=viewEpoch+1;setPanel('enemy-detail',panelHtml(header(e.name,`${BIOMES[e.biome].name} · ${e.boss?'Realm boss':e.behavior}`,'enemy-back')+`<img id="enemy-detail-art" class="codex-detail-art" alt="${e.name}"><p class="body-copy">${e.lore}</p><p class="muted">${e.boss?'Watch each warning before committing to an attack. Below half health, this guardian’s patterns become faster.':({caster:'Keep moving between spells. Close the distance after a cast.',charge:'Wait for the locked warning, then dodge across the charge.',ambush:'Legs plant before the lunge. Roll as the body strikes.',ranged:'Break the line of fire with a pillar, then approach.',slam:'Give the heavy impact room, then punish its recovery.',archer:'Arrows travel along a committed line. Approach at an angle.',lancer:'Respect the long thrust. Sidestep before striking.',duelist:'A patient guard leaves openings after a combination.',melee:'Guard the first blow or roll through it. Strike during recovery.'})[e.behavior]}</p><div class="button-row">${button('Idle','enemy-pose',{small:true,extra:'data-pose="idle"'})}${button('Walk','enemy-pose',{small:true,extra:'data-pose="walk"'})}${button('Attack','enemy-pose',{small:true,extra:'data-pose="attack"'})}</div><div class="button-row">${['s','n','e','w'].map(d=>button({s:'Front',n:'Back',e:'Right',w:'Left'}[d],'enemy-facing',{small:true,extra:`data-facing="${d}"`})).join('')}</div><p class="fine-print">The illustrated preview preserves the original pixel scale and authored timing.</p>`));detailAnimation={name:e.asset,state:'idle',facing:'s',time:0,epoch};await loadImage(e.asset);}
let detailAnimation=null;
function formatTime(t){return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function merchant(){if(!game)return;const stocks=game.room.stock??[];let html=header('The nameless keeper','Gold buys what the bell has left behind.')+`<p class="body-copy">“Take something with a name. It is harder for the dark to swallow.”</p><p class="eyebrow">${game.gold} GOLD</p>`;for(let n=0;n<stocks.length;n++){const s=stocks[n],item=createItem(s.baseId,game.floor,s.seed,1),b=ITEM_BY_ID[s.baseId];html+=`<article class="skill-card"><div><img data-item-icon="${b.id}" alt=""><div><h2>${item.name}</h2><small>${b.kind} · ${RARITIES[item.quality].name} · Level ${item.level}</small></div></div><p>${Object.entries(item.stats).map(([k,v])=>'+'+v+' '+statName(k)).join(' · ')}</p>${button(s.sold?'Taken':`Purchase · ${item.value*2} gold`,'buy',{small:true,disabled:s.sold||game.gold<item.value*2,extra:`data-index="${n}"`})}</article>`;}setPanel('merchant',panelHtml(html));fillPanelArt();}
function claimRun(won=false){if(!game||game.rewardClaimed)return 0;game.rewardClaimed=true;const earned=Math.floor(game.kills/4)+Math.floor(game.floor/5)+(won?60:0);profile.embers+=earned;profile.bestFloor=Math.max(profile.bestFloor,game.floor);profile.discovered=[...new Set([...profile.discovered,...game.seen])];if(won)profile.victories++;if(game.kills>=25&&!profile.achievements.includes('Bellbreaker'))profile.achievements.push('Bellbreaker');if(game.floor>=10&&!profile.achievements.includes('First Keeper'))profile.achievements.push('First Keeper');if(won&&!profile.achievements.includes('Dawnbringer'))profile.achievements.push('Dawnbringer');persistProfile();write(saveKey,null);return earned;}
function gameOver(){if(!game||gameOverShown)return;gameOverShown=true;const embers=claimRun(false);setPanel('result',`<section class="screen result-screen"><img class="screen-art" src="${ASSETS['overture-4'].image}" alt="The dark stair beneath the bell"><span class="eyebrow">The ember remembers</span><h1>OATH FALLEN</h1><p>The bell has your name.<br>Another wanderer will carry the light.</p><div class="result-stats"><span>Floor reached<b>${game.floor} / 100</b></span><span>Realm<b>${game.biome.name}</b></span><span>Enemies defeated<b>${game.kills}</b></span><span>Time beneath<b>${formatTime(game.runTime)}</b></span><span>Embers carried home<b>+${embers}</b></span></div>${button('Take another oath','retry',{primary:true})}<button class="text-button" data-command="title">Return to title</button></section>`);}
function endingChoice(){setPanel('ending-choice',`<section class="screen result-screen"><img class="screen-art" src="${ASSETS['overture-8'].image}" alt="The first light over the ruined kingdom"><span class="eyebrow">Floor one hundred</span><h1>THE FINAL BELL</h1><p>The hollow crown lies broken. You hold the last note of a dying kingdom.</p><div class="menu-actions full-width">${button('Let the stolen names go','ending-silence',{primary:true})}${button('Become the last keeper','ending-keeper')}</div></section>`);}
function victory(){const earned=claimRun(true);setPanel('victory',`<section class="screen result-screen"><img class="screen-art" src="${ASSETS['overture-8'].image}" alt="Dawn over Vespergrave"><span class="eyebrow">A hundred floors. An answered oath.</span><h1>DAWN RETURNED</h1><p>${game.hero.name} carried the last ember below.<br>The world will see another morning.</p><div class="result-stats"><span>Depth conquered<b>100 / 100</b></span><span>Guardians laid to rest<b>10</b></span><span>Enemies defeated<b>${game.kills}</b></span><span>Time beneath<b>${formatTime(game.runTime)}</b></span><span>Embers carried home<b>+${earned}</b></span></div>${button('Share the dawn','share',{primary:true})}<button class="text-button" data-command="title">Return to title</button></section>`);}
function skipTutorial(){if(!game?.tutorial)return;game.tutorial=null;game.layout=generateFloor(game.seed,1);game.enemies=[];game.enterRoom(0);game.player.hp=game.player.maxHp;game.player.focus=game.player.maxFocus;profile.tutorialDone=true;persistProfile();backgroundKey='';updateVisibility();saveRun();}
async function syncSkillIcons(){if(!game)return;const attackImage=document.querySelector('.touch-action.attack img'),attackLabel=document.querySelector('.touch-action.attack small'),weapon=game.inventory.find(i=>i.uid===game.equipment.weapon);if(attackImage)attackImage.src=await iconThumb('campaign-items',weapon?.baseId??('item-abbey-'+game.hero.weapon));if(attackLabel)attackLabel.textContent=game.hero.id==='seer'?'CAST':'ATTACK';for(let n=0;n<2;n++){const id=game.skills[n],el=$('skill-icon-'+(n+1));el.src=id?await iconThumb('campaign-skills',id):UI_ICONS.star;el.style.opacity=id?'1':'.3';el.parentElement.setAttribute('aria-label',id?SKILLS.find(s=>s.id===id).name:'Empty skill slot');}}
function projectPage(feedback=false){const url=PROJECT_URL+(feedback?'/issues':'');if(window.VespergraveNative?.openProject)window.VespergraveNative.openProject(feedback);else window.open(url,'_blank','noopener,noreferrer');}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el||el.disabled)return;audio.start();try{
 if(el.dataset.hero){selectedHero=el.dataset.hero;updateHeroSelection();return;}
 if(el.dataset.difficulty){selectedDifficulty=el.dataset.difficulty;updateHeroSelection();return;}
 if(el.dataset.bagTab){bagTab=el.dataset.bagTab;await renderBag();return;}
 if(el.dataset.item){selectItem(el.dataset.item);return;}
 if(el.dataset.enemy){await enemyDetail(el.dataset.enemy);return;}
 if(el.dataset.eventChoice){if(game.resolveEvent(el.dataset.eventChoice)){setPanel(null);saveRun();syncSkillIcons();}else await eventDialog();return;}
 if(el.dataset.rating){profile.rating=Number(el.dataset.rating);persistProfile();for(const b of overlay.querySelectorAll('[data-rating]'))b.classList.toggle('selected',Number(b.dataset.rating)<=profile.rating);$('rating-copy').textContent=`Your rating: ${profile.rating} / 5. Thank you for playing.`;return;}
 const c=el.dataset.command;if(!c)return;
 if(c==='title'||c==='save-title'){saveRun();title();}
 else if(c==='close')closePanel();else if(c==='new-game'||c==='hero-select')await heroSelect();else if(c==='begin')beginFlow();else if(c==='confirm-new')confirmNew();else if(c==='continue')await continueRun();else if(c==='resume')setPanel(null);else if(c==='settings')showSettings();else if(c==='about')showAbout();else if(c==='share')await shareGame();else if(c==='rate')showRating();else if(c==='project'||c==='feedback')projectPage(c==='feedback');else if(c==='bag')await openBag();
 else if(c==='bond'){const rank=profile.ranks[selectedHero],cost=(rank+1)*20;if(rank<10&&profile.embers>=cost){profile.embers-=cost;profile.ranks[selectedHero]++;persistProfile();updateHeroSelection();}}
 else if(c==='onboarding-next'){if(onboardingPage<2){onboardingPage++;onboarding();}else afterOnboarding();}else if(c==='onboarding-skip')afterOnboarding();else if(c==='cinematic-next')cinematicNext();else if(c==='cinematic-skip')finishCinematic();else if(c==='replay-intro')playCinematic(INTRO,()=>game?togglePause():title());else if(c==='skip-tutorial')skipTutorial();
 else if(c==='item-equip'){const uid=el.dataset.uid,item=game.inventory.find(i=>i.uid===uid),b=ITEM_BY_ID[item?.baseId];if(b?.slot)game.equip(uid);else game.consume(uid);await renderBag();saveRun();}
 else if(c==='item-salvage'){game.salvage(el.dataset.uid);await renderBag();saveRun();}
 else if(c==='skill-equip'){game.equipSkill(el.dataset.id,Number(el.dataset.slot));await renderBag();syncSkillIcons();saveRun();}else if(c==='skill-upgrade'){game.upgradeSkill(el.dataset.id);await renderBag();saveRun();}
 else if(c==='codex-prev'||c==='codex-next'){codexBiome=(codexBiome+(c==='codex-next'?1:9))%10;codexEnemy=null;if(game&&panel==='bag')await renderBag();else await showCodex();}
 else if(c==='title-codex')await showCodex();else if(c==='enemy-back'){detailAnimation=null;await showCodex();}else if(c==='enemy-pose'&&detailAnimation){detailAnimation.state=el.dataset.pose;detailAnimation.time=0;}else if(c==='enemy-facing'&&detailAnimation){detailAnimation.facing=el.dataset.facing;detailAnimation.time=0;}
 else if(c==='buy'){game.buy(Number(el.dataset.index));merchant();saveRun();}else if(c==='retry'){game=null;gameOverShown=false;await heroSelect();}else if(c==='ending-silence'||c==='ending-keeper')playCinematic([ENDINGS[c==='ending-keeper'?1:0]],victory);
 }catch(e){showError(e);}});
document.addEventListener('input',event=>{const el=event.target,key=el.dataset.setting;if(!key)return;settings[key]=el.type==='checkbox'?el.checked:key==='fps'?Number(el.value):Number(el.value)/100;write(settingsKey,settings);audio.apply();updateVisibility();});
$('open-bag').onclick=()=>openBag();
const gameplayKeys=new Set(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','KeyJ','KeyK','Space','KeyQ','KeyE','KeyR','KeyF','KeyI','Escape']);
window.addEventListener('keydown',e=>{if(!gameplayKeys.has(e.code)||e.target.matches('input,select,textarea'))return;e.preventDefault();audio.start();if(e.repeat)return;if(e.code==='Escape'){if(panel==='cinematic')finishCinematic();else if(panel&&game)closePanel();else togglePause();return;}if(e.code==='KeyI'){if(game){if(panel==='bag')setPanel(null);else openBag();}return;}if(panel||!game)return;keys.add(e.code);if(['Space','KeyQ','KeyE','KeyR','KeyF'].includes(e.code))queued.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(game&&!panel)togglePause();audio.voice?.pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();saveRun();audio.context?.suspend();audio.voice?.pause();if(game&&!panel)togglePause();}else audio.context?.resume().catch(()=>{});});
function input(){const t=touch.consume(),i={up:t.up||keys.has('KeyW')||keys.has('ArrowUp'),down:t.down||keys.has('KeyS')||keys.has('ArrowDown'),left:t.left||keys.has('KeyA')||keys.has('ArrowLeft'),right:t.right||keys.has('KeyD')||keys.has('ArrowRight'),attack:t.attack||keys.has('KeyJ'),block:t.block||keys.has('KeyK'),roll:t.roll||queued.has('Space'),skill1:t.skill1||queued.has('KeyQ'),skill2:t.skill2||queued.has('KeyE'),heal:t.heal||queued.has('KeyR'),interact:t.interact||queued.has('KeyF')};queued.clear();return i;}
function resize(){const box=app.getBoundingClientRect();canvas.width=360;canvas.height=Math.max(470,Math.round(360*box.height/box.width));ctx.imageSmoothingEnabled=false;game?.resize(arenaHeight());backgroundKey='';}
window.addEventListener('resize',resize);if(window.visualViewport)window.visualViewport.addEventListener('resize',resize);
function pixelText(c,text,x,y,color='#d4c49d',scale=1,center=false){text=String(text).toUpperCase();let width=0;for(const ch of text)width+=((FONT.glyphs[ch]?.[0]?.length??3)+1)*scale;if(center)x-=Math.floor(width/2);c.fillStyle=color;for(const ch of text){const g=FONT.glyphs[ch];if(g){for(let yy=0;yy<g.length;yy++)for(let xx=0;xx<g[yy].length;xx++)if(g[yy][xx]!=='.'&&g[yy][xx]!==' ')c.fillRect(Math.round(x+xx*scale),Math.round(y+yy*scale),scale,scale);}x+=((g?.[0]?.length??3)+1)*scale;}}
function paintFloorTile(c,t){const seal=t.type==='arena-seal',name=seal?'arena-seals':'layout-kit',img=imageReady(name),f=frames(name)[tag(name,game.biome.id+'-'+(seal?'seal':t.type))?.from??0]?.frame;if(!img||!f)return;if(seal){c.drawImage(img,f.x,f.y,f.w,f.h,t.x-80,t.y+32-56,160,112);return;}const h=t.height??80,x=Math.round(t.x-40),y=Math.round(t.y+32-h/2);if(h===80){c.drawImage(img,f.x,f.y,80,80,x,y,80,80);return;}c.drawImage(img,f.x,f.y,80,28,x,y,80,28);for(let yy=28;yy<h-33;yy+=16){const n=Math.min(16,h-33-yy);c.drawImage(img,f.x,f.y+28,80,n,x,y+yy,80,n);}c.drawImage(img,f.x,f.y+47,80,33,x,y+h-33,80,33);}
function roomBackground(){const name='room-'+game.biome.id,key=`${name}/${game.floor}/${game.room.id}/${game.room.layout}/${canvas.height}`;if(backgroundKey===key&&background)return background;const img=imageReady(name),headers=imageReady('room-headers'),kit=imageReady('layout-kit');if(!img||!headers||!kit)return null;background=document.createElement('canvas');background.width=360;background.height=canvas.height;const c=background.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle=game.biome.palette[0];c.fillRect(0,0,360,canvas.height);const h=game.arena.height,offset=32;c.drawImage(img,0,0,360,120,0,offset,360,120);for(let y=120;y<h-32;y+=16){let sy=120+(y-120)%480;if(sy>=296&&sy<360)sy=144+(sy%32);const take=Math.min(16,h-32-y);c.drawImage(img,0,sy,360,take,0,y+offset,360,take);}const head=frames('room-headers')[tag('room-headers',game.biome.id+'-'+game.arena.header)?.from??0].frame;c.drawImage(headers,head.x,head.y,head.w,head.h,0,32,360,120);for(const t of game.arena.floorTiles)paintFloorTile(c,t);c.drawImage(img,0,608,360,32,0,h,360,32);backgroundKey=key;return background;}
